ericTextbox("Chevron Speed", "Broadcast chevron movement speed in pixels per second.", "Appearance", "rts.actionreplay.broadcast.chevronSpeed", 95, 10, 500); ui.BeginRow(); ui.AddColorPicker("Title Prefix / Suffix Colour", "Colour of the Broadcast title decoration.", "Appearance", "rts.actionreplay.broadcast.decorationColor", "#0384CBFF"); ui.AddColorPicker("Title Colour", "Colour of the Broadcast title text.", "Appearance", "rts.actionreplay.broadcast.titleColor", "#FFFFFFFF"); ui.EndRow(); ui.EndSection(); ui.BeginSection("Cut", "Appearance"); ui.BeginRow(); ui.AddColorPicker("Primary Colour", "Cut Primary colour.", "Appearance", "rts.actionreplay.cut.primaryColor", "#0384CBFF"); ui.AddColorPicker("Secondary Colour", "Cut Secondary colour.", "Appearance", "rts.actionreplay.cut.secondaryColor", "#FFD400FF"); ui.EndRow(); ui.BeginRow(); ui.AddNumericTextbox("Block Width", "Cut block width in pixels.", "Appearance", "rts.actionreplay.cut.blockWidth", 170, 1, 1000); ui.AddToggleSwitch("Random", "Randomize each Cut block width.", "Appearance", "rts.actionreplay.cut.randomWidth", true); ui.AddNumericTextbox("Bar Height", "Cut accent bar height in pixels.", "Appearance", "rts.actionreplay.cut.barHeight", 5, 1, 50); ui.EndRow(); ui.BeginRow(); ui.AddColorPicker("Title Prefix / Suffix Colour", "Colour of the Cut title decoration.", "Appearance", "rts.actionreplay.cut.decorationColor", "#0384CBFF"); ui.AddColorPicker("Title Colour", "Colour of the Cut title text.", "Appearance", "rts.actionreplay.cut.titleColor", "#FFFFFFFF"); ui.EndRow(); ui.EndSection(); ui.EndSection();
